// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    // fuzzed params: depositor private key (used to get an address) and deposit amount
    function testFuzz_property(uint256 depositorKey, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        depositorKey = bound(depositorKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep domain reasonable: non-zero depositor and amount within balanceable range
        depositorKey = bound(depositorKey, 1, type(uint256).max);
        amount = bound(amount, 1, 1 ether);

        address depositor = vm.addr(uint256(depositorKey));
        // fund depositor so they can deposit
        vm.deal(depositor, amount);

        // Deploy a helper that will REVERT on receive to simulate a failing callee when C sends funds
        Reverter rev = new Reverter();

        // depositor deposits into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Now set the depositor's credited balance to be the reverter's address by impersonating reverter
        // We need to have c.credit[msg.sender] be >0 for withdrawAll to attempt the external call.
        // The contract credits by msg.sender, so to have c attempt to send to rev, we must have rev be msg.sender.
        // So we simulate that by having the reverter call deposit (so credit[reverter] == amount)
        vm.deal(address(rev), amount);
        vm.prank(address(rev));
        c.deposit{value: amount}();

        // At this point credit[address(rev)] == amount. Now when rev calls withdrawAll(), C will attempt
        // to call back to rev via a low-level call{value:amount} which will revert inside Reverter.receive().

        bool ok;
        // call withdrawAll as rev; if the reference contract has require(callResult) then the call should revert
        vm.prank(address(rev));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: For the reference C, withdrawAll MUST revert (ok == false) whenever the recipient's receive() reverts.
        // The mutant that removes require(callResult) will allow ok == true for some inputs (here any amount>0),
        // so this single assertion distinguishes them.
        assertTrue(!ok);
    }
}

// Adversarial helper that reverts on receiving Ether
contract Reverter {
    receive() external payable {
        revert("revert receive");
    }
}
